fn fib(n: u64) -> u64 {
    if n < 2 {
        return n;
    }
    // push fib(n - 2) onto my deque, run fib(n - 1) myself
    let (a, b) = rayon::join(|| fib(n - 1), || fib(n - 2));
    a + b
}

void push(Deque *q, int x) {      // owner only
  long b = load_explicit(&q->bottom, relaxed);
  long t = load_explicit(&q->top, acquire);
  Array *a = load_explicit(&q->array, relaxed);
  if (b - t > a->size - 1) {       // full: grow
    resize(q);
    a = load_explicit(&q->array, relaxed);
  }
  store_explicit(&a->buffer[b % a->size], x, relaxed);
  thread_fence(release);           // publish the task before bottom
  store_explicit(&q->bottom, b + 1, relaxed);
}

int steal(Deque *q) {              // any thief
  long t = load_explicit(&q->top, acquire);
  thread_fence(seq_cst);
  long b = load_explicit(&q->bottom, acquire);
  int x = EMPTY;
  if (t < b) {
    Array *a = load_explicit(&q->array, consume);
    x = load_explicit(&a->buffer[t % a->size], relaxed);
    if (!compare_exchange_strong_explicit(&q->top, &t, t + 1,
                                          seq_cst, relaxed))
      return ABORT;                // lost a race: caller retries
  }
  return x;
}

int take(Deque *q) {             // owner only
  long b = load(&q->bottom) - 1;
  Array *a = load(&q->array);
  store(&q->bottom, b);            // reserve slot b
  thread_fence(seq_cst);
  long t = load(&q->top);
  int x;
  if (t <= b) {                    // not empty
    x = load(&a->buffer[b % a->size]);
    if (t == b) {                  // last task: race thieves
      if (!cas(&q->top, &t, t + 1))
        x = EMPTY;                 // a thief won
      store(&q->bottom, b + 1);
    }
  } else {                         // already empty
    x = EMPTY;
    store(&q->bottom, b + 1);
  }
  return x;
}
